// Custom iterable + iterator:
const range = {
  [Symbol.iterator](){ // iterable protocol
    let i = 0;
    return {
      next() {          // iterator protocol
        return i < 3 ? {value: i++, done:false} : {value:undefined, done:true};
      }
    };
  }
};
[...range]; // [0, 1, 2]
for(const n of range) console.log(n); // 0 1 2

function* gen() {
  console.log('start');
  const x = yield 1;
  console.log('x is', x);
  const y = yield 2;
  console.log('y is', y);
  return 3;
}
const g = gen();
console.log(g.next());
console.log(g.next(10));
console.log(g.next(20));

function* range(start, end, step = 1) {
  for (let i = start; i < end; i += step) {
    yield i;
  }
}

for (const n of range(0, 10, 2)) {
  console.log(n); // 0, 2, 4, 6, 8
}

// Infinite generator — only computes when needed:
function* naturals() {
  let n = 0;
  while (true) yield n++;
}
const gen = naturals();
gen.next().value; // 0
gen.next().value; // 1

// Two-way communication:
function* adder() {
  let total = 0;
  while (true) {
    const input = yield total;
    total += input;
  }
}
const a = adder();
a.next();    // {value:0, done:false}
a.next(5);   // {value:5, done:false}
a.next(3);   // {value:8, done:false}
